--
-- Table structure for table `in_patient_admissions`
--

DROP TABLE IF EXISTS `in_patient_admissions`;
CREATE TABLE IF NOT EXISTS `in_patient_admissions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `patient_id` bigint NOT NULL,
  `ward_id` int NOT NULL,
  `bed_id` int NOT NULL,
  `consultant_id` int DEFAULT NULL,
  `included_medicine` int NOT NULL DEFAULT '1',
  `g4no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `consultant_procedure_id` int DEFAULT NULL,
  `guardian_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `emergency_contact_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `relation_id` int DEFAULT NULL,
  `admission_date` datetime DEFAULT NULL,
  `discharge_date` datetime DEFAULT NULL,
  `discharge_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `canelation_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_active` int NOT NULL DEFAULT '1',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `admission_status` enum('Admit','Canceled','Discharged','Reffered') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Admit',
  `consultant_share` decimal(10,2) NOT NULL,
  `consultant_share_amount` double(10,2) NOT NULL DEFAULT '0.00',
  `procedure_rate` decimal(10,2) NOT NULL,
  `total_amount_received_from_patient` decimal(10,2) NOT NULL DEFAULT '0.00',
  `sec_procedure_rate` decimal(10,2) NOT NULL DEFAULT '0.00',
  `investigation_cost` double(10,2) NOT NULL DEFAULT '0.00',
  `service_charges_cost` double(10,2) NOT NULL DEFAULT '0.00',
  `medicine_cost` double(10,2) NOT NULL DEFAULT '0.00',
  `totalCost` double(10,2) NOT NULL DEFAULT '0.00',
  `balance` double(10,2) NOT NULL DEFAULT '0.00',
  `consultant_shares_payment_invoice_id` bigint NOT NULL DEFAULT '0',
  `amount_received_from_sehat_card` double(10,2) DEFAULT NULL,
  `patient_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'sehat_card',
  `advance_payment` decimal(10,2) NOT NULL DEFAULT '0.00',
  `security_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `discharge_by` int DEFAULT NULL,
  `is_posted` int NOT NULL DEFAULT '0',
  `posted_on` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ward_id` (`ward_id`),
  KEY `patient_id` (`patient_id`),
  KEY `bed_id` (`bed_id`),
  KEY `admission_type_id` (`consultant_procedure_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

