--
-- Table structure for table `in_patient_payments`
--

DROP TABLE IF EXISTS `in_patient_payments`;
CREATE TABLE IF NOT EXISTS `in_patient_payments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` bigint NOT NULL,
  `admission_id` bigint NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `payment_type` varchar(100) NOT NULL,
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `created_by` int NOT NULL,
  `created_at` datetime NOT NULL,
  `is_active` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

