--
-- Table structure for table `patient_discharge_checklist`
--

DROP TABLE IF EXISTS `patient_discharge_checklist`;
CREATE TABLE IF NOT EXISTS `patient_discharge_checklist` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `admission_id` int DEFAULT NULL,
  `patient_id` int DEFAULT NULL,
  `cnic` int DEFAULT NULL,
  `shp_form` int DEFAULT NULL,
  `ultrasound` int DEFAULT NULL,
  `doctor_prescription` int DEFAULT NULL,
  `labs` int DEFAULT NULL,
  `admission_form` int DEFAULT NULL,
  `nursing_notes` int DEFAULT NULL,
  `medication_chart` int DEFAULT NULL,
  `ot_notes` int DEFAULT NULL,
  `consern_notes` int DEFAULT NULL,
  `discharge_slip` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1727 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

