--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
CREATE TABLE IF NOT EXISTS `products` (
  `ProductID` int NOT NULL AUTO_INCREMENT,
  `store_id` int NOT NULL DEFAULT '1',
  `main_category_id` int DEFAULT NULL,
  `sub_category_id` int DEFAULT NULL,
  `item_form_id` int DEFAULT NULL,
  `item_make_id` int DEFAULT NULL,
  `generic_name_id` int DEFAULT NULL,
  `ProductName` varchar(255) DEFAULT NULL,
  `BrandID` int DEFAULT '0',
  `UnitID` int DEFAULT '0',
  `specification_name` varchar(200) DEFAULT NULL,
  `BarCode` varchar(255) DEFAULT '123',
  `pack_price` decimal(10,2) DEFAULT NULL,
  `pack_size` decimal(10,2) DEFAULT NULL,
  `PurchasePrice` decimal(10,2) DEFAULT '0.00',
  `SalePrice` decimal(10,2) DEFAULT '0.00',
  `low_limit` int DEFAULT '0',
  `CreatedBy` int DEFAULT NULL,
  `CreatedAt` date DEFAULT NULL,
  `ModifiedBy` int DEFAULT NULL,
  `ModifiedAt` date DEFAULT NULL,
  `IsActive` int DEFAULT '1',
  `zakat_purchase_price` int NOT NULL DEFAULT '0',
  `zakat_qty` int NOT NULL DEFAULT '0',
  `taxPercentage` decimal(10,2) DEFAULT NULL,
  `total_amount_of_avaliable_stock` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_amount_of_purchase_stock` decimal(10,2) NOT NULL DEFAULT '0.00',
  `avaliable_quantity` decimal(10,2) NOT NULL DEFAULT '0.00',
  `phy_avaliable_quantity` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`ProductID`)
) ENGINE=InnoDB AUTO_INCREMENT=1654 DEFAULT CHARSET=latin1;

