--
-- Table structure for table `receivables_details`
--

DROP TABLE IF EXISTS `receivables_details`;
CREATE TABLE IF NOT EXISTS `receivables_details` (
  `RDID` int NOT NULL AUTO_INCREMENT,
  `SCID` int DEFAULT NULL,
  `InvoiceNo` varchar(255) DEFAULT NULL,
  `Payment_type_ID` int DEFAULT NULL,
  `BankID` int DEFAULT NULL,
  `Amount` decimal(10,2) DEFAULT NULL,
  `FromAccount` varchar(255) DEFAULT NULL,
  `ToAccount` varchar(255) DEFAULT NULL,
  `ChecqueNo` int DEFAULT NULL,
  `ChecqueDate` date DEFAULT NULL,
  `TransferCode` varchar(255) DEFAULT NULL,
  `Description` varchar(255) DEFAULT NULL,
  `CreatedBy` int DEFAULT NULL,
  `CreatedAt` date DEFAULT NULL,
  `ModifiedBy` int DEFAULT NULL,
  `ModifiedAt` date DEFAULT NULL,
  `TransectionNo` int DEFAULT NULL,
  `Date` date DEFAULT NULL,
  PRIMARY KEY (`RDID`),
  KEY `SCID` (`SCID`),
  KEY `Payment_type_ID` (`Payment_type_ID`),
  KEY `BankID` (`BankID`),
  KEY `Date` (`Date`),
  KEY `SCID_2` (`SCID`),
  KEY `Payment_type_ID_2` (`Payment_type_ID`),
  KEY `BankID_2` (`BankID`),
  KEY `Date_2` (`Date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

