--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
CREATE TABLE IF NOT EXISTS `users` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `department_id` int NOT NULL,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `cnic` varchar(255) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `contact_number` varchar(100) DEFAULT NULL,
  `district_id` int DEFAULT NULL,
  `tehsil_id` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `username` varchar(255) DEFAULT NULL,
  `company_id` int DEFAULT NULL,
  `section_id` int DEFAULT NULL,
  `parent_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1',
  `description` text,
  `is_hod` varchar(100) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `device_token` text,
  `android_token` varchar(255) DEFAULT NULL,
  `ios_token` varchar(255) DEFAULT NULL,
  `is_specific` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `users_email_unique` (`email`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12275 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC;

